const fileName = $input.item.json.name || 'unknown';
const fileId = $input.item.json.id || '';
const isPdf = fileName.toLowerCase().endsWith('.pdf');

if (!isPdf) {
  return { json: { fileName, fileId, _skip: true, _reason: `Unsupported file type: ${fileName}` } };
}

const binary = $input.item.binary || {};
const keys = Object.keys(binary);

if (!keys.length) {
  return { json: { fileName, fileId, _skip: true, _reason: 'No binary data' } };
}

return {
  json: { fileName, fileId, _skip: false },
  binary: { data: binary[keys[0]] }
};

const input = $input.first().json;
const GEMINI_API_KEY = $env.GEMINI_API_KEY;

if (!input.text || input.text.length < 10) {
  return [{ json: { _skip: true, _reason: 'No readable text', source_file: input.fileName, file_id: input.fileId } }];
}

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${GEMINI_API_KEY}`,
  json: true,
  body: {
    contents: [{ parts: [{ text: input.text.substring(0, 1000) }] }]
  }
});

const raw = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let data;
try { data = JSON.parse(raw); } catch {
  return [{ json: { _skip: true, _reason: 'Invalid JSON', source_file: input.fileName, file_id: input.fileId } }];
}

return [{ json: { ...data, source_file: input.fileName, file_id: input.fileId } }];

const input = $input.item.json;
return {
  json: {
    file_name: input.source_file || input.fileName || 'unknown',
    file_id: input.file_id || input.fileId || '',
    error: input._reason || 'Unknown error',
    failed_at: new Date().toISOString()
  }
};
